CREATE SCHEMA habittrove;
SET LOCAL search_path = habittrove, pg_catalog;
CREATE TABLE schema_version (singleton boolean PRIMARY KEY CHECK(singleton), version integer NOT NULL);
INSERT INTO schema_version(singleton,version) VALUES (true,1);
CREATE TABLE documents (kind text PRIMARY KEY CHECK(kind IN ('auth','habits','wishlist','coins','settings','admin')), revision bigint NOT NULL DEFAULT 1, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE users (id text PRIMARY KEY, ordinal integer NOT NULL, username text NOT NULL, password_hash text, email text, is_admin boolean, auth_version integer, attributes jsonb NOT NULL);
CREATE UNIQUE INDEX user_name_identity ON users (lower(username));
CREATE TABLE oidc_identities (user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE, issuer text, subject text NOT NULL);
CREATE UNIQUE INDEX oidc_identity ON oidc_identities (COALESCE(issuer,''),subject);
CREATE TABLE permissions (user_id text REFERENCES users ON DELETE CASCADE, ordinal integer NOT NULL, resource text NOT NULL CHECK(resource IN ('habit','wishlist','coins')), can_write boolean NOT NULL, can_interact boolean NOT NULL, PRIMARY KEY(user_id,ordinal,resource));
CREATE TABLE manager_assignments (manager_id text REFERENCES users ON DELETE CASCADE, member_id text NOT NULL REFERENCES users, ordinal integer NOT NULL, PRIMARY KEY(manager_id,ordinal), UNIQUE(manager_id,member_id));
CREATE TABLE folders (user_id text REFERENCES users ON DELETE CASCADE, ordinal integer NOT NULL, id text NOT NULL, name text NOT NULL, PRIMARY KEY(user_id,ordinal), UNIQUE(user_id,id));
CREATE TABLE folder_items (user_id text, folder_ordinal integer, ordinal integer NOT NULL, item_id text NOT NULL, PRIMARY KEY(user_id,folder_ordinal,ordinal), FOREIGN KEY(user_id,folder_ordinal) REFERENCES folders ON DELETE CASCADE);
CREATE TABLE status_days (user_id text REFERENCES users ON DELETE CASCADE, ordinal integer NOT NULL, local_date date NOT NULL, status text NOT NULL, PRIMARY KEY(user_id,ordinal));
CREATE TABLE invitations (token_hash text PRIMARY KEY, ordinal integer NOT NULL, email text NOT NULL, created_by text NOT NULL, managed_by text, expires_at timestamptz NOT NULL, attributes jsonb NOT NULL);
CREATE TABLE habits (id text PRIMARY KEY, ordinal integer NOT NULL, revision bigint NOT NULL DEFAULT 1, name text NOT NULL, created_by text, requires_approval boolean, archived boolean, coin_reward numeric NOT NULL CHECK(coin_reward NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)), attributes jsonb NOT NULL);
CREATE TABLE habit_assignees (habit_id text REFERENCES habits ON DELETE CASCADE, ordinal integer NOT NULL, user_id text NOT NULL REFERENCES users, PRIMARY KEY(habit_id,ordinal));
CREATE TABLE habit_approvers (habit_id text REFERENCES habits ON DELETE CASCADE, ordinal integer NOT NULL, user_id text NOT NULL REFERENCES users, PRIMARY KEY(habit_id,ordinal));
CREATE TABLE checklist_entries (habit_id text REFERENCES habits ON DELETE CASCADE, ordinal integer NOT NULL, id text NOT NULL, text text NOT NULL, completed boolean NOT NULL, PRIMARY KEY(habit_id,ordinal));
-- Historical actor IDs deliberately have no FK: deleting an account must not erase its events.
CREATE TABLE completions (habit_id text REFERENCES habits ON DELETE CASCADE, ordinal integer NOT NULL, completed_at timestamptz, timestamp_text text, record_kind text NOT NULL CHECK(record_kind IN ('absent','null','record')), id text, actor_id text, beneficiary_id text, request_id text, voided boolean, approval text CHECK(approval IN ('pending','approved','rejected')), reward_amount numeric CHECK(reward_amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)), reviewed_by text, reviewed_at timestamptz, evidence_id text, evidence_mime text, attributes jsonb, PRIMARY KEY(habit_id,ordinal));
CREATE UNIQUE INDEX completion_id ON completions(habit_id,id) WHERE id IS NOT NULL;
CREATE UNIQUE INDEX completion_request ON completions(habit_id,request_id) WHERE request_id IS NOT NULL;
CREATE TABLE completion_recipients (habit_id text, completion_ordinal integer, ordinal integer NOT NULL, user_id text NOT NULL, PRIMARY KEY(habit_id,completion_ordinal,ordinal), FOREIGN KEY(habit_id,completion_ordinal) REFERENCES completions ON DELETE CASCADE);
CREATE TABLE slips (habit_id text REFERENCES habits ON DELETE CASCADE, ordinal integer NOT NULL, id text NOT NULL, actor_id text NOT NULL, occurred_at timestamptz NOT NULL, penalty numeric NOT NULL CHECK(penalty NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)), attributes jsonb NOT NULL, PRIMARY KEY(habit_id,ordinal), UNIQUE(habit_id,id));
CREATE TABLE wishlist_items (id text PRIMARY KEY, ordinal integer NOT NULL, revision bigint NOT NULL DEFAULT 1, name text NOT NULL, coin_cost numeric NOT NULL CHECK(coin_cost NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)), attributes jsonb NOT NULL);
CREATE TABLE wishlist_assignees (item_id text REFERENCES wishlist_items ON DELETE CASCADE, ordinal integer NOT NULL, user_id text NOT NULL REFERENCES users, PRIMARY KEY(item_id,ordinal));
-- A ledger owner is global. Stage B adds a family origin, never a family-owned wallet.
CREATE TABLE coin_ledger (id text PRIMARY KEY, ordinal integer NOT NULL, user_id text, actor_id text, related_item_id text, completion_id text, request_id text, amount numeric NOT NULL CHECK(amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)), type text NOT NULL, occurred_at timestamptz NOT NULL, attributes jsonb NOT NULL);
CREATE INDEX ledger_owner ON coin_ledger(user_id);
CREATE UNIQUE INDEX ledger_request ON coin_ledger(request_id) WHERE request_id IS NOT NULL;
CREATE TABLE setting_sections (name text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE admin_configuration (name text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE migration_batches (source_digest text PRIMARY KEY, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE authentication_throttles (key_hash text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE job_leases (name text PRIMARY KEY, owner text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE attachments (id text PRIMARY KEY, habit_id text, completion_id text, owner_id text, path text NOT NULL, mime_type text NOT NULL, sha256 text);
REVOKE ALL ON SCHEMA habittrove FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA habittrove FROM PUBLIC;
